"""Embedding provider abstraction."""

from __future__ import annotations

from typing import Protocol

from backend.config import Settings


class Embedder(Protocol):
    model: str

    def embed_documents(self, texts: list[str]) -> list[list[float]]:
        ...

    def embed_query(self, text: str) -> list[float]:
        ...


class OllamaEmbedder:
    def __init__(self, settings: Settings) -> None:
        from langchain_ollama import OllamaEmbeddings

        kwargs = {"model": settings.ollama_embedding_model}
        if settings.ollama_base_url:
            kwargs["base_url"] = settings.ollama_base_url
        self.model = settings.ollama_embedding_model
        self._embeddings = OllamaEmbeddings(**kwargs)

    def embed_documents(self, texts: list[str]) -> list[list[float]]:
        if not texts:
            return []
        return [list(vector) for vector in self._embeddings.embed_documents(texts)]

    def embed_query(self, text: str) -> list[float]:
        return list(self._embeddings.embed_query(text))


class VoyageEmbedder:
    def __init__(self, settings: Settings) -> None:
        if not settings.voyage_api_key:
            raise RuntimeError("VOYAGE_API_KEY is required when EMBEDDING_PROVIDER=voyage.")
        try:
            import voyageai
        except ImportError as exc:  # pragma: no cover - dependency branch
            raise RuntimeError("Install the voyageai package to use Voyage embeddings.") from exc

        self.model = settings.embedding_model
        self.output_dimension = settings.embedding_dimensions
        self.batch_size = settings.embedding_batch_size
        self._client = voyageai.Client(api_key=[REDACTED]

    def embed_documents(self, texts: list[str]) -> list[list[float]]:
        return self._embed(texts, input_type="document")

    def embed_query(self, text: str) -> list[float]:
        return self._embed([text], input_type="query")[0]

    def _embed(self, texts: list[str], input_type: str) -> list[list[float]]:
        if not texts:
            return []

        vectors: list[list[float]] = []
        for offset in range(0, len(texts), self.batch_size):
            batch = texts[offset : offset + self.batch_size]
            kwargs = {
                "texts": batch,
                "model": self.model,
                "input_type": input_type,
            }
            if self.output_dimension > 0:
                kwargs["output_dimension"] = self.output_dimension
            response = self._client.embed(**kwargs)
            vectors.extend([list(vector) for vector in response.embeddings])
        return vectors


def create_embedder(settings: Settings) -> Embedder:
    if settings.embedding_provider == "voyage":
        return VoyageEmbedder(settings)
    if settings.embedding_provider == "ollama":
        return OllamaEmbedder(settings)
    raise ValueError(f"Unsupported EMBEDDING_PROVIDER: {settings.embedding_provider}")

