"""Reranking helpers."""

from __future__ import annotations

from dataclasses import replace

from backend.config import Settings
from backend.models import SearchResult


class VoyageReranker:
    def __init__(self, settings: Settings) -> None:
        if not settings.voyage_api_key:
            raise RuntimeError("VOYAGE_API_KEY is required for Voyage reranking.")
        try:
            import voyageai
        except ImportError as exc:  # pragma: no cover - dependency branch
            raise RuntimeError("Install the voyageai package to use Voyage reranking.") from exc

        self.model = settings.rerank_model
        self._client = voyageai.Client(api_key=[REDACTED]

    def rerank(self, query: str, results: list[SearchResult], top_k: int) -> list[SearchResult]:
        if not results:
            return []

        response = self._client.rerank(
            query=query,
            documents=[result.text for result in results],
            model=self.model,
            top_k=min(top_k, len(results)),
        )

        reranked: list[SearchResult] = []
        for item in response.results:
            source = results[item.index]
            reranked.append(replace(source, rerank_score=float(item.relevance_score)))
        return reranked


def create_reranker(settings: Settings) -> VoyageReranker | None:
    if not settings.rerank_enabled:
        return None
    return VoyageReranker(settings)

"""Vector-store adapters for ChromaDB and MongoDB Atlas Vector Search."""

from __future__ import annotations

import logging
import time
from typing import Protocol

from backend.config import Settings
from backend.models import ChunkRecord, SearchResult

log = logging.getLogger(__name__)


class VectorStore(Protocol):
    name: str

    def reset(self) -> None:
        ...

    def upsert_chunks(self, chunks: list[ChunkRecord], embeddings: list[list[float]]) -> None:
        ...

    def similarity_search(
        self,
        query_embedding: list[float],
        *,
        k: int,
        num_candidates: int | None = None,
    ) -> list[SearchResult]:
        ...

    def count(self) -> int:
        ...

    def stats(self) -> dict:
        ...


class ChromaVectorStore:
    name = "chroma"

    def __init__(self, settings: Settings) -> None:
        import chromadb

        self.collection_name = settings.collection_name
        if settings.chroma_host:
            self._client = chromadb.HttpClient(host=settings.chroma_host, port=settings.chroma_port)
        else:
            self._client = chromadb.PersistentClient(path=settings.chroma_persist_dir)

    def _collection_names(self) -> set[str]:
        names: set[str] = set()
        for collection in self._client.list_collections():
            names.add(str(getattr(collection, "name", collection)))
        return names

    def _collection(self):
        return self._client.get_or_create_collection(
            name=self.collection_name,
            metadata={"hnsw:space": "cosine"},
        )

    def reset(self) -> None:
        if self.collection_name in self._collection_names():
            self._client.delete_collection(self.collection_name)
        self._collection()

    def upsert_chunks(self, chunks: list[ChunkRecord], embeddings: list[list[float]]) -> None:
        if len(chunks) != len(embeddings):
            raise ValueError("Chunk and embedding counts do not match.")
        if not chunks:
            return
        collection = self._collection()
        collection.upsert(
            ids=[chunk.id for chunk in chunks],
            documents=[chunk.text for chunk in chunks],
            embeddings=embeddings,
            metadatas=[chunk.metadata for chunk in chunks],
        )

    def similarity_search(
        self,
        query_embedding: list[float],
        *,
        k: int,
        num_candidates: int | None = None,
    ) -> list[SearchResult]:
        output = self._collection().query(
            query_embeddings=[query_embedding],
            n_results=k,
            include=["documents", "metadatas", "distances"],
        )
        ids = output.get("ids", [[]])[0] or []
        documents = output.get("documents", [[]])[0] or []
        metadatas = output.get("metadatas", [[]])[0] or []
        distances = output.get("distances", [[]])[0] or []

        results: list[SearchResult] = []
        for index, chunk_id in enumerate(ids):
            distance = distances[index] if index < len(distances) else None
            score = None if distance is None else 1.0 - float(distance)
            results.append(
                SearchResult(
                    id=chunk_id,
                    text=documents[index] if index < len(documents) else "",
                    metadata=metadatas[index] if index < len(metadatas) else {},
                    score=score,
                )
            )
        return results

    def count(self) -> int:
        return int(self._collection().count())

    def stats(self) -> dict:
        return {"count": self.count(), "collection": self.collection_name}


class MongoDBVectorStore:
    name = "mongodb"

    def __init__(self, settings: Settings) -> None:
        from pymongo import MongoClient

        self.settings = settings
        self.index_name = settings.mongodb_vector_index
        self.dimensions = settings.embedding_dimensions
        self.client = MongoClient(settings.mongodb_uri)
        self.database = self.client[settings.mongodb_database]
        self.collection = self.database[settings.mongodb_collection]

    def reset(self) -> None:
        self.collection.drop()
        self._ensure_index()

    def upsert_chunks(self, chunks: list[ChunkRecord], embeddings: list[list[float]]) -> None:
        if len(chunks) != len(embeddings):
            raise ValueError("Chunk and embedding counts do not match.")
        if not chunks:
            return

        self._ensure_index()

        from pymongo import ReplaceOne

        operations = []
        for chunk, embedding in zip(chunks, embeddings):
            operations.append(
                ReplaceOne(
                    {"_id": chunk.id},
                    {
                        "_id": chunk.id,
                        "text": chunk.text,
                        "embedding": embedding,
                        "metadata": chunk.metadata,
                    },
                    upsert=True,
                )
            )
        if operations:
            self.collection.bulk_write(operations, ordered=False)

    def similarity_search(
        self,
        query_embedding: list[float],
        *,
        k: int,
        num_candidates: int | None = None,
    ) -> list[SearchResult]:
        candidates = num_candidates or max(k, k * self.settings.mongodb_num_candidates_multiplier)
        pipeline = [
            {
                "$vectorSearch": {
                    "index": self.index_name,
                    "path": "embedding",
                    "queryVector": query_embedding,
                    "numCandidates": max(candidates, k),
                    "limit": k,
                }
            },
            {
                "$project": {
                    "_id": 1,
                    "text": 1,
                    "metadata": 1,
                    "score": {"$meta": "vectorSearchScore"},
                }
            },
        ]
        return [
            SearchResult(
                id=str(row["_id"]),
                text=row.get("text", ""),
                metadata=row.get("metadata", {}),
                score=float(row["score"]) if "score" in row else None,
            )
            for row in self.collection.aggregate(pipeline)
        ]

    def count(self) -> int:
        return int(self.collection.count_documents({}))

    def stats(self) -> dict:
        payload: dict = {"count": self.count(), "collection": self.collection.name}
        try:
            stats = self.database.command("collStats", self.collection.name)
            payload["storage_size_bytes"] = stats.get("storageSize")
            payload["total_index_size_bytes"] = stats.get("totalIndexSize")
        except Exception as exc:  # pragma: no cover - optional server metadata
            payload["stats_error"] = str(exc)
        return payload

    def _ensure_index(self) -> None:
        if self._index_exists():
            return

        from pymongo.operations import SearchIndexModel

        definition = {
            "fields": [
                {
                    "type": "vector",
                    "path": "embedding",
                    "numDimensions": self.dimensions,
                    "similarity": "cosine",
                },
                {"type": "filter", "path": "metadata.article_id"},
                {"type": "filter", "path": "metadata.topic"},
            ]
        }
        model = SearchIndexModel(definition=definition, name=self.index_name, type="vectorSearch")
        self.collection.create_search_index(model=model)
        self._wait_for_index()

    def _index_exists(self) -> bool:
        try:
            return any(index.get("name") == self.index_name for index in self.collection.list_search_indexes())
        except Exception:
            return False

    def _wait_for_index(self) -> None:
        deadline = time.monotonic() + self.settings.mongodb_index_timeout_seconds
        last_index: dict | None = None

        while time.monotonic() < deadline:
            indexes = list(self.collection.list_search_indexes())
            last_index = next((index for index in indexes if index.get("name") == self.index_name), None)
            if last_index:
                status = str(last_index.get("status", "")).upper()
                queryable = last_index.get("queryable")
                if queryable is True or status in {"READY", "QUERYABLE"}:
                    return
                if "status" not in last_index and "queryable" not in last_index:
                    return
            time.sleep(1)

        raise TimeoutError(f"MongoDB vector index {self.index_name!r} was not ready: {last_index}")


def create_vector_store(settings: Settings) -> VectorStore:
    if settings.vector_store == "chroma":
        return ChromaVectorStore(settings)
    if settings.vector_store == "mongodb":
        return MongoDBVectorStore(settings)
    raise ValueError(f"Unsupported VECTOR_STORE: {settings.vector_store}")

